"""Migration of the Meridian CRM nightly case-escalation job."""

from datetime import date
from typing import Any


def _legacy_value(row: dict[str, Any], column: str) -> Any:
    """Return a column value using CRMScript's empty uninitialized value."""
    value = row.get(column, "")
    return "" if value is None else value


def _parse_legacy_date(value: Any) -> date | None:
    """Convert a legacy YYYYMMDD value, including its null sentinel."""
    if value in ("", "00000000", None):
        return None

    text = str(value)
    if len(text) != 8 or not text.isdigit():
        raise ValueError(f"invalid legacy date: {text!r}")

    return date(int(text[0:4]), int(text[4:6]), int(text[6:8]))


def _datediff(first: Any, second: Any) -> int:
    """Implement CRMScript DATEDIFF as whole calendar days."""
    first_date = _parse_legacy_date(first)
    second_date = _parse_legacy_date(second)
    if first_date is None or second_date is None:
        return 0
    return (first_date - second_date).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return auto-escalation events in ascending CASE_ID order."""
    events: list[dict] = []

    live_cases = (
        case
        for case in cases
        if _legacy_value(case, "DEL_FLG") != "Y"
    )

    for case in sorted(
        live_cases,
        key=lambda row: str(_legacy_value(row, "CASE_ID")),
    ):
        status = _legacy_value(case, "STAT_CD")
        age = _datediff(today, _legacy_value(case, "OPEN_DT"))

        should_escalate = (
            status == "N" and age >= 2
        ) or (
            status == "A"
            and _legacy_value(case, "ESC_FLG") != "Y"
            and age >= 7
        )

        if should_escalate:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(_legacy_value(case, "CASE_ID")),
                    "event": "auto_escalate",
                }
            )

    return events
